from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,cells))
    return out
def f(g):
    cs=comps(g)
    big={c for c,s in cs if len(s)>1}
    out=[row[:] for row in g]
    for c,cells in cs:
        if len(cells)==1:
            y,x=cells[0]
