from collections import Counter
def f2(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    cs=comps(g)
    tot=Counter(c for c,_ in cs)
    for c,cells in cs:
        if len(cells)==1:
            y,x=cells[0]
            cnt=Counter()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<h and 0<=nx<w and g[ny][nx]!=c:
                    cnt[g[ny][nx]]+=1
            mv,cntm=cnt.most_common(1)[0]
            # tie-break: pick color with smaller total count in grid
            if cntm==max(cnt.values()):
                best=min((cc for cc in cnt if cnt[cc]==cntm),key=lambda cc:tot[cc])
            else:
                best,mv=cnt.most_common(1)[0]
            out[y][x]=best
    return out
